-- name: by_schema
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT schema_name, table_name, constraint_name, constraint_type, check_clause, is_enforced FROM (
SELECT DISTINCT TRIM(i.DatabaseName) AS schema_name, TRIM(i.TableName) AS table_name, COALESCE(NULLIF(TRIM(i.IndexName), ''), CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 'PK_' || TRIM(i.TableName) ELSE 'UQ_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) END) AS constraint_name, CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 'PRIMARY KEY' ELSE 'UNIQUE' END AS constraint_type, CAST(NULL AS VARCHAR(1)) AS check_clause, 'Y' AS is_enforced FROM DBC.IndicesV i JOIN DBC.TablesV t ON UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(i.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND (TRIM(i.IndexType) IN ('K', 'U') OR (TRIM(i.IndexType) IN ('P', 'Q') AND TRIM(i.UniqueFlag) = 'Y'))
UNION ALL SELECT DISTINCT TRIM(r.ChildDB), TRIM(r.ChildTable), COALESCE(NULLIF(TRIM(r.IndexName), ''), 'FK_' || TRIM(r.ChildTable) || '_' || CAST(r.IndexID AS VARCHAR(12))), 'FOREIGN KEY', CAST(NULL AS VARCHAR(1)), CASE WHEN TRIM(COALESCE(r.InconsistencyFlag, 'N')) = 'Y' THEN 'N' ELSE 'Y' END FROM DBC.All_RI_ChildrenV r WHERE UPPER(TRIM(r.ChildDB)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(r.ChildDB)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')
UNION ALL SELECT TRIM(tc.DatabaseName), TRIM(tc.TableName), COALESCE(NULLIF(TRIM(tc.ConstraintName), ''), 'CK_' || TRIM(tc.TableName)), 'CHECK', TRIM(tc.ConstraintText), 'Y' FROM DBC.Table_LevelConstraintsV tc WHERE UPPER(TRIM(tc.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(tc.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')
UNION ALL SELECT TRIM(c.DatabaseName), TRIM(c.TableName), 'CK_' || TRIM(c.TableName) || '_' || TRIM(c.ColumnName), 'CHECK', TRIM(c.ColumnConstraint), 'Y' FROM DBC.ColumnsV c JOIN DBC.TablesV t ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(c.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND c.ColumnConstraint IS NOT NULL AND TRIM(c.ColumnConstraint) <> ''
) c ORDER BY schema_name, table_name, constraint_type, constraint_name;

-- name: by_table
-- dialect: teradata
LOCKING ROW FOR ACCESS
SELECT schema_name, table_name, constraint_name, constraint_type, check_clause, is_enforced FROM (
SELECT DISTINCT TRIM(i.DatabaseName) AS schema_name, TRIM(i.TableName) AS table_name, COALESCE(NULLIF(TRIM(i.IndexName), ''), CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 'PK_' || TRIM(i.TableName) ELSE 'UQ_' || TRIM(i.TableName) || '_' || CAST(i.IndexNumber AS VARCHAR(12)) END) AS constraint_name, CASE WHEN TRIM(i.IndexType) IN ('K', 'P', 'Q') THEN 'PRIMARY KEY' ELSE 'UNIQUE' END AS constraint_type, CAST(NULL AS VARCHAR(1)) AS check_clause, 'Y' AS is_enforced FROM DBC.IndicesV i JOIN DBC.TablesV t ON UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(i.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(i.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND (TRIM(i.IndexType) IN ('K', 'U') OR (TRIM(i.IndexType) IN ('P', 'Q') AND TRIM(i.UniqueFlag) = 'Y'))  AND UPPER(TRIM(i.TableName)) = UPPER(TRIM(:table_name))
UNION ALL SELECT DISTINCT TRIM(r.ChildDB), TRIM(r.ChildTable), COALESCE(NULLIF(TRIM(r.IndexName), ''), 'FK_' || TRIM(r.ChildTable) || '_' || CAST(r.IndexID AS VARCHAR(12))), 'FOREIGN KEY', CAST(NULL AS VARCHAR(1)), CASE WHEN TRIM(COALESCE(r.InconsistencyFlag, 'N')) = 'Y' THEN 'N' ELSE 'Y' END FROM DBC.All_RI_ChildrenV r WHERE UPPER(TRIM(r.ChildDB)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(r.ChildDB)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')  AND UPPER(TRIM(r.ChildTable)) = UPPER(TRIM(:table_name))
UNION ALL SELECT TRIM(tc.DatabaseName), TRIM(tc.TableName), COALESCE(NULLIF(TRIM(tc.ConstraintName), ''), 'CK_' || TRIM(tc.TableName)), 'CHECK', TRIM(tc.ConstraintText), 'Y' FROM DBC.Table_LevelConstraintsV tc WHERE UPPER(TRIM(tc.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(tc.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS')  AND UPPER(TRIM(tc.TableName)) = UPPER(TRIM(:table_name))
UNION ALL SELECT TRIM(c.DatabaseName), TRIM(c.TableName), 'CK_' || TRIM(c.TableName) || '_' || TRIM(c.ColumnName), 'CHECK', TRIM(c.ColumnConstraint), 'Y' FROM DBC.ColumnsV c JOIN DBC.TablesV t ON UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(t.DatabaseName)) AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(t.TableName)) WHERE UPPER(TRIM(c.DatabaseName)) = UPPER(TRIM(COALESCE(:schema_name, DATABASE))) AND UPPER(TRIM(c.DatabaseName)) NOT IN ('DBC', 'SYSUDTLIB', 'SYSLIB', 'TD_SYSFNLIB', 'SYSSPATIAL', 'SYSBAR', 'LOCKLOGSHREDDER', 'SQLJ', 'TDSTATS', 'TD_SERVER_DB', 'CRASHDUMPS') AND TRIM(t.TableKind) IN ('T', 'O') AND c.ColumnConstraint IS NOT NULL AND TRIM(c.ColumnConstraint) <> ''  AND UPPER(TRIM(c.TableName)) = UPPER(TRIM(:table_name))
) c ORDER BY schema_name, table_name, constraint_type, constraint_name;
